-- Called only after read-only Alfa checks prove that this payment already exists.
-- The unknown -> done transition, order link, result, and polling queue entry commit atomically.
create or replace function public.le_v2_recover_bank_order(
  p_order_id text,
  p_payment_id text,
  p_bank_status integer,
  p_bank_amount_kopecks bigint,
  p_payment_url text,
  p_description text
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $function$
declare
  v_order public.le_v2_orders%rowtype;
  v_effect public.le_v2_order_effects%rowtype;
  v_queue_id text;
  v_result jsonb;
begin
  if coalesce(trim(p_order_id), '') = '' or coalesce(trim(p_payment_id), '') = '' or length(p_payment_id) > 36 then
    raise exception 'Invalid recovery identifiers' using errcode = '22023';
  end if;
  if p_bank_status is null or p_bank_status not in (0, 2) then
    raise exception 'Bank status requires manual review' using errcode = '22023';
  end if;
  if p_bank_amount_kopecks is null or p_bank_amount_kopecks < 0 then
    raise exception 'Invalid bank amount' using errcode = '22023';
  end if;

  select * into v_order from public.le_v2_orders where order_id = p_order_id for update;
  if not found then raise exception 'Order not found' using errcode = 'P0002'; end if;
  if v_order.payment_method <> 'card' then
    raise exception 'Only card orders can be recovered' using errcode = '22023';
  end if;
  if round(v_order.total * 100) <> p_bank_amount_kopecks then
    raise exception 'Bank amount does not match stored order' using errcode = '22023';
  end if;
  if v_order.payment_id is not null and v_order.payment_id <> p_payment_id then
    raise exception 'Order already has a different payment ID' using errcode = '23505';
  end if;
  if v_order.result ? 'paymentId' and v_order.result->>'paymentId' <> p_payment_id then
    raise exception 'Order result contains a different payment ID' using errcode = '23505';
  end if;
  if p_bank_status <> 2 and coalesce(trim(p_payment_url), '') = '' then
    raise exception 'Unpaid recovery requires a verified payment form URL' using errcode = '22023';
  end if;

  select * into v_effect
    from public.le_v2_order_effects
   where effect_key = 'bank:' || p_order_id
   for update;
  if not found or v_effect.state <> 'unknown' then
    raise exception 'Bank effect must be unknown and inactive before recovery' using errcode = '55000';
  end if;

  v_result := jsonb_build_object(
    'url', coalesce(p_payment_url, ''),
    'paymentId', p_payment_id,
    'orderId', p_order_id,
    'amount', v_order.total,
    'description', coalesce(p_description, ''),
    'paid', p_bank_status = 2
  );

  insert into public.le_v2_payment_orders(md_order, order_number, amount, description, status)
  values (p_payment_id, p_order_id, v_order.total, left(coalesce(p_description, ''), 512),
          case when p_bank_status = 2 then 'paid' else 'pending' end)
  on conflict (md_order) do update set
    order_number = excluded.order_number,
    amount = excluded.amount,
    description = coalesce(public.le_v2_payment_orders.description, excluded.description),
    status = case when public.le_v2_payment_orders.status = 'paid' or p_bank_status = 2 then 'paid' else 'pending' end,
    created_at = case when public.le_v2_payment_orders.notified_at is null then now() else public.le_v2_payment_orders.created_at end,
    last_checked_at = now(),
    last_error = null
  where public.le_v2_payment_orders.order_number = excluded.order_number
    and public.le_v2_payment_orders.amount = excluded.amount
  returning md_order into v_queue_id;
  if v_queue_id is null then
    raise exception 'Payment queue contains a conflicting bank order' using errcode = '23505';
  end if;

  update public.le_v2_orders set
    payment_id = p_payment_id,
    result = v_result,
    status = case when status = 'paid' or p_bank_status = 2 then 'paid' else 'awaiting_payment' end,
    last_checked_at = now(),
    last_error = null,
    updated_at = now()
  where order_id = p_order_id;

  update public.le_v2_order_effects set
    state = 'done',
    result = v_result,
    last_error = null,
    updated_at = now()
  where effect_key = 'bank:' || p_order_id and state = 'unknown';
  if not found then raise exception 'Bank effect changed during recovery' using errcode = '55000'; end if;

  return v_result;
end;
$function$;

revoke all on function public.le_v2_recover_bank_order(text, text, integer, bigint, text, text) from public, anon, authenticated;
grant execute on function public.le_v2_recover_bank_order(text, text, integer, bigint, text, text) to service_role;


-- Prepared locally. Apply after order_idempotency, before deploying the updated pay handler.

alter table public.le_v2_orders
  add column notification_checked_at timestamptz,
  add column notification_chat_ids jsonb;
alter table public.le_v2_order_effects
  add column attempt_count integer not null default 1 check (attempt_count > 0),
  add column next_attempt_at timestamptz;
update public.le_v2_order_effects set next_attempt_at = updated_at + interval '1 minute'
where state = 'failed' and effect_key like 'telegram:cash_on_delivery:%';
create index le_v2_orders_cod_delivery_queue on public.le_v2_orders
  (notification_checked_at asc nulls first, created_at)
  where payment_method = 'cash_on_delivery' and status = 'accepted' and not telegram_sent;


-- Prepared locally. NOT applied to production: apply with the order migrations before deploying pay (see supabase/DEPLOY.md).
-- Fixed-window counters for order admission and the shared external-call budget.
-- A request takes all of its buckets atomically: either every counter is incremented or none is.

create table public.le_v2_rate_limits (
  bucket text not null check (length(bucket) between 1 and 200),
  window_start timestamptz not null,
  hits integer not null default 0 check (hits >= 0),
  primary key (bucket, window_start)
);
alter table public.le_v2_rate_limits enable row level security;
revoke all on public.le_v2_rate_limits from public, anon, authenticated;
grant select, insert, update, delete on public.le_v2_rate_limits to service_role;

-- Returns 0 when admitted, otherwise the Retry-After value in seconds (nothing is counted then).
create or replace function public.le_v2_rate_limit_take(p_buckets text[], p_limits integer[], p_windows integer[])
returns integer
language plpgsql
security definer
set search_path = public, pg_temp
as $function$
declare
  v_now timestamptz := clock_timestamp();
  v_start timestamptz;
  v_hits integer;
  v_retry integer := 0;
  i integer;
begin
  if p_buckets is null or p_limits is null or p_windows is null
     or cardinality(p_buckets) = 0 or cardinality(p_buckets) > 16
     or cardinality(p_buckets) <> cardinality(p_limits) or cardinality(p_buckets) <> cardinality(p_windows) then
    raise exception 'Invalid rate limit request' using errcode = '22023';
  end if;
  for i in 1 .. cardinality(p_buckets) loop
    if p_buckets[i] is null or length(p_buckets[i]) not between 1 and 200
       or p_limits[i] is null or p_limits[i] < 1
       or p_windows[i] is null or p_windows[i] < 1 or p_windows[i] > 86400 then
      raise exception 'Invalid rate limit request' using errcode = '22023';
    end if;
  end loop;

  begin
    for i in 1 .. cardinality(p_buckets) loop
      v_start := to_timestamp(floor(extract(epoch from v_now) / p_windows[i]) * p_windows[i]);
      insert into public.le_v2_rate_limits as l (bucket, window_start, hits)
      values (p_buckets[i], v_start, 1)
      on conflict (bucket, window_start) do update set hits = l.hits + 1
      returning l.hits into v_hits;
      if v_hits > p_limits[i] then
        v_retry := greatest(v_retry, 1,
          ceil(extract(epoch from (v_start + make_interval(secs => p_windows[i]) - v_now)))::integer);
      end if;
    end loop;
    if v_retry > 0 then
      raise exception 'le_rate_limited' using errcode = 'P0001';
    end if;
  exception when sqlstate 'P0001' then
    -- Subtransaction rollback: a refused request consumes no budget. Local variables keep their values.
    if sqlerrm = 'le_rate_limited' then return v_retry; end if;
    raise;
  end;

  delete from public.le_v2_rate_limits
   where ctid in (select ctid from public.le_v2_rate_limits where window_start < v_now - interval '2 days' limit 100);
  return 0;
end;
$function$;

revoke all on function public.le_v2_rate_limit_take(text[], integer[], integer[]) from public, anon, authenticated;
grant execute on function public.le_v2_rate_limit_take(text[], integer[], integer[]) to service_role;


commit;
notify pgrst, 'reload schema';
